using CreatorEngine;

public sealed partial class Mover : Component
{
    public override void PostPhysics(float tick)
    {
        if (!HasTransform) return;
        if (Input.GetKey(KeyCode.W))
            Transform.Translate(new Float3(0f, 0f, 2f * tick));
    }
}

using System.Threading.Tasks;
using CreatorEngine;

public sealed partial class DelayedMove : Component
{
    public override async Task OnSimulate()
    {
        await Scope.Delay(1f);
        if (IsAlive && HasTransform)
            Transform.Translate(new Float3(0f, 1f, 0f));
    }
}

